#!/usr/bin/env php
<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
$dir=(string)Config::get('BACKUP_DIR','');if($dir===''||!str_starts_with($dir,'/')){fwrite(STDERR,"Set BACKUP_DIR to an absolute directory outside the web root.\n");exit(1);}if(!is_dir($dir)&&!mkdir($dir,0700,true)){fwrite(STDERR,"Unable to create backup directory.\n");exit(1);}$file=rtrim($dir,'/').'/atlas-'.gmdate('Ymd-His').'.sql';$command=['mysqldump','--single-transaction','--skip-comments','--host='.(string)Config::get('DB_HOST','localhost'),'--port='.(string)Config::get('DB_PORT','3306'),'--user='.(string)Config::get('DB_USER',''),(string)Config::get('DB_NAME','atlas')];$env=$_ENV;$env['MYSQL_PWD']=(string)Config::get('DB_PASS','');$process=proc_open($command,[0=>['pipe','r'],1=>['file',$file,'w'],2=>['pipe','w']],$pipes,null,$env);if(!is_resource($process)){fwrite(STDERR,"Unable to start mysqldump.\n");exit(1);}fclose($pipes[0]);$error=stream_get_contents($pipes[2]);fclose($pipes[2]);$code=proc_close($process);if($code!==0||!is_file($file)||filesize($file)<100){@unlink($file);fwrite(STDERR,"Backup failed: {$error}\n");exit(1);}chmod($file,0600);$retention=max(1,(int)Config::get('BACKUP_RETENTION_DAYS','30'));foreach(glob(rtrim($dir,'/').'/atlas-*.sql')?:[] as $old)if(filemtime($old)<time()-($retention*86400))unlink($old);fwrite(STDOUT,"Backup created: {$file}\n");
